  Definition e_aux : expr :=
    EAlu Instr.ALU_ADD (EMd Instr.M_MUL (ELit 32768) (EVar 0)) (EAlu Instr.ALU_ADD (EMd Instr.M_MUL (ELit 8) (EVar 1))
      (EAlu Instr.ALU_ADD (EMd Instr.M_MUL (ELit 8) (EVar 2)) (EAlu Instr.ALU_ADD (EMd Instr.M_MUL (ELit 4096) (EVar 6)) (EMd Instr.M_MUL (ELit 16) (EVar 10))))).
  Definition e_rnd : expr :=
    EAlu Instr.ALU_ADD (EMd Instr.M_MUL (ELit 32768) (EVar 0)) (EAlu Instr.ALU_ADD (EMd Instr.M_MUL (ELit 8) (EVar 1))
      (EAlu Instr.ALU_ADD (EMd Instr.M_MUL (ELit 8) (EVar 2)) (EAlu Instr.ALU_ADD (EMd Instr.M_MUL (ELit 8) (EVar 4))
        (EAlu Instr.ALU_ADD (EMd Instr.M_MUL (ELit 4096) (EVar 6)) (EMd Instr.M_MUL (ELit 16) (EVar 10)))))).
  Definition aux_offs : list Z := map (fun j => 24 + 8 * Z.of_nat j) (seq 0 20).
  Definition kblob1 (b : expr) (off n : Z) (K : kentry) : bool :=
    match K with KBlob (SA kb kk) (ELit kn) _ => (expr_eqb kb b && (kk =? off) && (kn =? n))%bool | _ => false end.
  (* [comment removed for export] *)
  Definition spres_f (g : bool) (cls : nat) (ch : acs) : bool :=
      (forallb (fun off => match kread8e BSEGS2 (kn ch) e_sp0_early off with Some _ => true | None => false end) [0; 8; 16]
      && forallb (fun off => match kread8e BSEGS2 (kn ch) e_aux off with Some _ => true | None => false end) aux_offs
      && existsb (kblob1 e_rnd 184 16) (kn ch))%bool.
  Lemma spres_check_ok : all_holes spres_f = true.
  Proof. vm_cast_no_check (@eq_refl bool true). Qed.
