  (* [comment removed for export] *)
  Lemma kread8e_present : forall b off, (exists v, kread8e BSEGS2 (kn ch) b off = Some v) ->
    0x684000 <= uE E b + off -> uE E b + off + 8 <= 2 ^ 64 -> (forall i, 0 <= i < 8 -> HID (Z_to_bv 64 (uE E b + off + i)) = false) ->
