  Lemma sp_hidden : forall z, AB0 (wa z) = true -> exists x, FULL (wa z) = Some x.
  Proof.
    intros z HB.
    apply (hidden_present BSEGS2 BOTH_H BPH2 sp0 rdraw brk0 brk0 (in_argv inp) (in_envp inp) (in_image_fs inp) (in_stdin inp) (in_uid inp) (in_gid inp)
                  (in_hwcap inp) (in_groups inp) (in_net inp) (in_nofile inp) (in_sigmask inp) (in_abort_terminal inp) (in_va_size inp) (in_urandom inp) (in_tmp inp)
                  Vsp Vav Vev Vfit E FULL (wa z) (co_sinv _ _ _ _ _ _ _ _ _ _ _ HC)).
    rewrite (argH0_SINV0 BPH2 sp0 rdraw brk0 (in_argv inp) (in_envp inp) (in_uid inp) (in_hwcap inp) Vsp Vav Vev Vfit E FULL _ (co_sinv _ _ _ _ _ _ _ _ _ _ _ HC)). exact HB.
  Qed.

  Lemma sp_full : forall z, sp0z - 8388608 <= z < pm_stack_top sp0z -> exists b, FULL (wa z) = Some b.
  Proof.
    intros z Hz.
    destruct (Z.lt_ge_cases z sp0z) as [BELOW|ABOVE].
    { (* [comment removed for export] *) exact (BoMainIfacePre.stack_full sp0 brk0 rdraw inp h ch E R FULL model Vsp Vbrk Vav Vev Hh HC z ltac:(lia)). }
    destruct (AB0 (wa z)) eqn:HB; [exact (sp_hidden z HB)|].
    destruct (sp_nh z ltac:(lia) HB) as [Z1|[Z2|Z3]]; [apply sp_case1; lia | apply sp_case2; exact Z2 | apply sp_case3; exact Z3].
  Qed.

